import{_ as d,a0 as p,w as r,s as o,ao as t,I as s,x as i,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Arch Linux 下全面使用 Wayland 的配置指南 | LCTT x X-CMD","titleTemplate":false,"description":"Arch Linux 下全面使用 Wayland 的配置指南 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Arch Linux 下全面使用 Wayland 的配置指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Arch Linux 下全面使用 Wayland 的配置指南 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230516.0 ⭐️⭐️ Guide to Set up Full Wayland with Arch Linux","title":"Arch Linux 下全面使用 Wayland 的配置指南","tag":"202309","desc":""},"relativePath":"202309/20230516.0 ⭐️⭐️ Guide to Set up Full Wayland with Arch Linux.md","filePath":"[post].md"}'),g={name:"202309/20230516.0 ⭐️⭐️ Guide to Set up Full Wayland with Arch Linux.md"};function h(u,a,k,b,y,m){const l=p("Link");return r(),o("div",null,[a[43]||(a[43]=t('<h1 id="arch-linux-下全面使用-wayland-的配置指南" tabindex="-1">Arch Linux 下全面使用 Wayland 的配置指南 <a class="header-anchor" href="#arch-linux-下全面使用-wayland-的配置指南" aria-label="Permalink to “Arch Linux 下全面使用 Wayland 的配置指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/08/090159qe0jkbtj5z55bbeq.jpg" alt=""></p><blockquote><p>我們能否在 Arch Linux 中通過主流的桌面環境或窗口管理器來全面運行 Wayland？一起來探索答案。</p></blockquote><p>Wayland 是一種針對 Linux 運行圖形應用的高效、現代化的協議。相較之下，它在安全、穩定和圖形性能方面相較老舊的 X.Org 顯示服務器表現更出色。</p><p>儘管 X.Org 多年來一直是默認的顯示服務器，但其年代漫長且複雜度高，導致了許多問題，包括安全漏洞和對新型硬件的兼容性問題。而 Wayland 提供了一個更簡潔和安全的顯示協議，用以解決這些問題。</p><p>雖然向 Wayland 轉型已經有近十年的時間，但這是可以理解的。大型 Linux 發行版，例如 Ubuntu 和 Fedora，自 2021 年起就默認使用 Wayland，因為該協議現已逐漸穩定。</p><p>然而，對 Arch Linux 用户來説，使用 Wayland 進行自定義安裝可能會比較複雜。在所有主流桌面環境中，只有 KDE Plasma 和 GNOME 有最新的 Wayland 支持。Xfce、LXQt 及其他桌面環境正在開發支持 Wayland 的功能，但現在還沒有做好準備。</p><p>在窗口管理器方面，Sway 在 Arch Linux 中已經全面支持 Wayland。儘管如此，我還是希望能測試 Wayland 在 Arch 中的表現，並給你提供一個截至今日的狀態報告。</p><p>讓我們來嘗試在 Arch Linux 中配置 KDE Plasma 和 GNOME 以全面支持 Wayland。</p><h3 id="arch-linux-中的-wayland-設置" tabindex="-1">Arch Linux 中的 Wayland 設置 <a class="header-anchor" href="#arch-linux-中的-wayland-設置" aria-label="Permalink to “Arch Linux 中的 Wayland 設置”">​</a></h3>',10)),s("p",null,[a[1]||(a[1]=i("在理想的情況下，你應已經安裝了 ",-1)),n(l,{href:"https://archlinux.org/packages/extra/x86_64/wayland/"},{default:e(()=>[...a[0]||(a[0]=[i("基礎的 wayland 包",-1)])]),_:1}),a[2]||(a[2]=i("。打開一個終端，並通過運行下列命令進行核實：",-1))]),a[44]||(a[44]=t('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Qi wayland</span></span></code></pre></div><p>如果你尚未安裝，則可以使用以下命令進行安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed wayland</span></span></code></pre></div><h4 id="kde-plasma-桌面環境" tabindex="-1">KDE Plasma 桌面環境 <a class="header-anchor" href="#kde-plasma-桌面環境" aria-label="Permalink to “KDE Plasma 桌面環境”">​</a></h4>',4)),s("p",null,[a[4]||(a[4]=i("接下來的步驟設定的前提條件是你擁有一個沒有安裝任何桌面環境或窗口管理器的裸機 Arch Linux 環境。你可以通過使用 ",-1)),n(l,{href:"https://www.debugpoint.com/archinstall-guide/"},{default:e(()=>[...a[3]||(a[3]=[i("高效的 archinstall 腳本",-1)])]),_:1}),a[5]||(a[5]=i(" 進行 Arch Linux 的裸機安裝。",-1))]),s("p",null,[a[7]||(a[7]=i("在 Arch Linux 中，為了設置標準的 KDE Plasma，我們需要對 Wayland 進行一些調整。因此，該過程中需要從 AUR 安裝一些包進來，這就要求你已經 ",-1)),n(l,{href:"https://www.debugpoint.com/install-yay-arch/"},{default:e(()=>[...a[6]||(a[6]=[i("設置了 Yay",-1)])]),_:1}),a[8]||(a[8]=i(" 或者其他的 AUR 輔助工具。",-1))]),s("p",null,[a[10]||(a[10]=i("首先，利用以下命令從 AUR 安裝一個定製的 sddm 顯示管理器 Wayland 軟件包。請注意，這個 ",-1)),a[11]||(a[11]=s("code",null,"sddm",-1)),a[12]||(a[12]=i(" 包與 Arch Extra 倉庫中的 ",-1)),a[13]||(a[13]=s("code",null,"sddm",-1)),a[14]||(a[14]=i(" 包並不相同。根據 ",-1)),n(l,{href:"https://wiki.archlinux.org/title/wayland#Display_managers"},{default:e(()=>[...a[9]||(a[9]=[i("ArchWiki",-1)])]),_:1}),a[15]||(a[15]=i(" 的指南，只有 GDM 和 ",-1)),a[16]||(a[16]=s("code",null,"sddm-git",-1)),a[17]||(a[17]=i(" 在 Arch Linux 中提供了完善的 Wayland 支持。",-1))]),a[45]||(a[45]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yay -S sddm-git</span></span></code></pre></div><p>安裝完成後，執行下述命令來安裝更多 Wayland 包。</p><ul><li><code>xorg-xwayland</code>：使得 xclients 能在 Wayland 下運行</li><li><code>xorg-xlsclients</code>：列出正在一個顯示端口上運行的客户端應用（可選）</li><li><code>qt5-wayland</code>：為 Wayland 提供的 Qt API</li><li><code>glfw-wayland</code>：供 Wayland 使用的 GUI 應用開發包</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed xorg-xwayland xorg-xlsclients qt5-wayland glfw-wayland</span></span></code></pre></div><p>然後，執行以下命令以安裝 Plasma 和與 Wayland 會話關聯的應用。請保持以下的安裝順序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed plasma kde-applications</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed plasma-wayland-session</span></span></code></pre></div><p><strong>注意</strong>：如果你是英偉達用户，你可能需要考慮安裝 <code>egl-wayland</code> 包，但需要説明的是，我沒有嘗試過此操作。</p><p>我們現在來安裝 Firefox 和 Chromium，這樣能夠幫助我們測試 Wayland 是否正常運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed firefox chromium</span></span></code></pre></div><p>安裝完成後，啓動 sddm 顯示管理器和 NetworkManager 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable sddm</span></span>
<span class="line"><span>sudo systemctl enable NetworkManager</span></span></code></pre></div><p>另外，sddm 顯示管理器需要做一些額外設置。使用你喜歡的文本編輯器，打開 sddm 的配置文件，然後在 <code>[Theme]</code> 下面添加 <code>Current=breeze</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /usr/lib/sddm/sddm.conf.d/default.conf</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Theme]</span></span>
<span class="line"><span># current theme name</span></span>
<span class="line"><span>Current=breeze</span></span></code></pre></div><p>設置完成後，保存並關閉文件，然後進行重啓。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>重啓後，在登錄屏幕上，你應該可以看到 Wayland 的選項。選擇並登錄 KDE Plasma 的 Wayland 會話。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Plasma-Wayland-session-during-login.jpg" alt="Plasma Wayland 會話登錄界面"></p>`,19)),s("p",null,[a[19]||(a[19]=i("你還能通過查看 ",-1)),a[20]||(a[20]=s("code",null,"$XDG_SESSION_TYPE",-1)),a[21]||(a[21]=i(" 變量來 ",-1)),n(l,{href:"https://www.debugpoint.com/check-wayland-or-xorg/"},{default:e(()=>[...a[18]||(a[18]=[i("核實你是否在運行 Wayland",-1)])]),_:1}),a[22]||(a[22]=i("。",-1))]),a[46]||(a[46]=t(`<p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/KDE-Plasma-with-Wayland-in-Arch-Linux.jpg" alt="Arch Linux 中運行的 KDE Plasma 與 Wayland"></p><p>如果你希望強制讓 Firefox 以 Wayland 運行，那麼就在 <code>/etc/environment</code> 中添加以下行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MOZ_ENABLE_WAYLAND=1</span></span></code></pre></div><p>然後重新啓動或執行下方的命令使其生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source /etc/environment</span></span></code></pre></div><p>打開 Firefox，進入 <code>about:support</code> 頁面來校驗 “Window protocol” 的值。你也可以通過在終端中運行 <code>xlsclients</code> 來查看哪些外部應用正在運行在 Wayland 下。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Firefox-is-using-xwayland-in-KDE-Plasma-with-Arch.jpg" alt="在 Arch 和 KDE Plasma 下 Firefox 使用的是 xwayland"></p><p>至此，你已經完成了在 Arch Linux 中使用 Wayland 安裝配置 KDE Plasma 的全部步驟。</p><h4 id="wayland-kde-plasma-在-arch-中的性能表現" tabindex="-1">Wayland KDE Plasma 在 Arch 中的性能表現 <a class="header-anchor" href="#wayland-kde-plasma-在-arch-中的性能表現" aria-label="Permalink to “Wayland KDE Plasma 在 Arch 中的性能表現”">​</a></h4><p>總體而言，Arch Linux 下的 KDE Plasma 配合 Wayland 運行得相當順暢，未出現任何中斷使用或重大問題的情形。截圖和屏幕錄製應用 Spectacle 功能一切正常。儘管如此，我在測試過程中還是注意到了幾個小問題。</p><p>首先，在開啓如 Dolphin 這類應用程序時，底部面板時不時會出現閃爍，這主要是在 VirtualBox 會話中觀察到的。</p><p>其次，鼠標指針的變化行為有點奇怪。它無法適時地從指針狀態切換到操作手柄狀態（詳見下圖）。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Screencast-from-2023-05-15-17-30-51.webm" alt=""></p><p>最後，當從待機/屏幕關閉狀態恢復在線時（在沒有安裝客户機插件的 VirtualBox 中），KWin 會崩潰。雖然這可能只是虛擬機特有的現象，但仍然需要進行硬重啓才能返回到桌面。</p><p>在 Arch Linux 的 Wayland 會話閒置狀態下，內存消耗大約為 2GB。</p><h3 id="gnome" tabindex="-1">GNOME <a class="header-anchor" href="#gnome" aria-label="Permalink to “GNOME”">​</a></h3><p>在 Arch Linux 中，GDM 顯示管理器已經完全支持 Wayland。首先，我們通過下列命令安裝 GDM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed gdm</span></span></code></pre></div><p>安裝完畢後，使用以下命令安裝幾個 Wayland 需要的包。</p><ul><li><code>xorg-xwayland</code>：使得 xclients 能在 Wayland 下運行</li><li><code>xorg-xlsclients</code>：用於列出在顯示器上運行的應用程序（可選）</li><li><code>glfw-wayland</code>：Wayland 的圖形用户界面應用開發包</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed xorg-xwayland xorg-xlsclients glfw-wayland</span></span></code></pre></div><p>接下來，你可以用下面的一系列命令來安裝 GNOME 和一些與 Wayland 會話相關的應用。請確保按照下列給出的順序來執行這些命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S --needed gnome gnome-tweaks nautilus-sendto gnome-nettool gnome-usage gnome-multi-writer adwaita-icon-theme xdg-user-dirs-gtk fwupd arc-gtk-theme</span></span></code></pre></div><p><strong>注意</strong>：如果你正在使用英偉達，你可能需要安裝 <code>egl-wayland</code> 軟件包，但我並未親自試過此方法。</p><p>接下來，我們還要安裝 Firefox 和 Chromium，這樣你就能測試 Wayland 是否在 GNOME 中正常運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S --needed firefox chromium</span></span></code></pre></div><p>一旦這項任務完成，就啓動 GDM 顯示管理器和 NetworkManager 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable gdm</span></span>
<span class="line"><span>sudo systemctl enable NetworkManager</span></span></code></pre></div><p>保存並關閉文件之後，進行重啓。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reboot</span></span></code></pre></div><p>在登錄界面，你能看到 “GNOME (Wayland)” 選項。選擇並登錄到 GNOME 的 Wayland 會話中，以進入 Arch Linux。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/GNOME-with-Wayland-running-in-Arch-Linux.jpg" alt="在 Arch Linux 中運行的帶有 Wayland 的 GNOME"></p><h4 id="gnome-的性能" tabindex="-1">GNOME 的性能 <a class="header-anchor" href="#gnome-的性能" aria-label="Permalink to “GNOME 的性能”">​</a></h4><p>如果將 GNOME 和 KDE Plasma 進行對比，你會發現 GNOME 在 Arch Linux 的 Wayland 下的表現更勝一籌。沒有遇到重大問題或應用屏幕閃爍。這可能源於 GNOME 44 針對 Wayland 的最新改進已普及至 Arch Linux。</p><p>此外，Firefox 是在 GNOME 上直接在 Wayland 上運行，而不是使用 xwayland 包裝器。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Firefox-with-Wayland-in-GNOME.jpg" alt="在 GNOME 中的 Firefox 使用 Wayland"></p><h3 id="解決常見-wayland-問題" tabindex="-1">解決常見 Wayland 問題 <a class="header-anchor" href="#解決常見-wayland-問題" aria-label="Permalink to “解決常見 Wayland 問題”">​</a></h3><p>雖然 Wayland 提供了眾多優點，但在使用過程中你可能會遇到一些挑戰。以下列出了幾個常見的問題以及可能的解決方案：</p>`,38)),s("ul",null,[a[28]||(a[28]=s("li",null,[s("strong",null,"處理不兼容的應用程序"),i("：部分較舊或不常用的應用可能還未完全支持 Wayland。你可以考慮尋找專為 Wayland 設計的替代應用，或利用 XWayland 作為兼容性層。")],-1)),a[29]||(a[29]=s("li",null,[s("strong",null,"解決性能相關問題"),i("：如果你在特定的應用程序中遇到性能問題，確保你已經安裝了最新的圖形驅動。另外，也可以查看是否有特定的合成器設置或適用於特定應用程序的優化措施。")],-1)),s("li",null,[a[24]||(a[24]=i("在 ",-1)),n(l,{href:"https://wiki.archlinux.org/title/wayland#Troubleshooting"},{default:e(()=>[...a[23]||(a[23]=[i("這個頁面",-1)])]),_:1}),a[25]||(a[25]=i(" 中，也有",-1)),a[26]||(a[26]=s("strong",null,"更多",-1)),a[27]||(a[27]=i("疑難解答的建議。",-1))])]),a[47]||(a[47]=s("h3",{id:"結論",tabindex:"-1"},[i("結論 "),s("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),a[48]||(a[48]=s("p",null,"在 Arch Linux 中將 Wayland 設置為默認的顯示服務器可以大大提升安全性、穩定性和圖形性能。遵循本指南的安裝和配置步驟，你能夠從 Xorg 平穩過渡到 Wayland，享受一個更為現代高效的顯示體驗。",-1)),a[49]||(a[49]=s("p",null,"然而，對於 Arch Linux 加 Wayland 的組合來説，整個過程可能會顯得稍微複雜一些，因為許多問題崩潰時都需要額外的注意。",-1)),a[50]||(a[50]=s("p",null,"這個指南並沒包括在 Arch 使用 Wayland 遊戲的測試，所以你可能需要在配置完成後自行試驗。我希望這篇教程能幫助你在 Arch Linux 中配置 Wayland。",-1)),a[51]||(a[51]=s("p",null,"如果你有任何進展，歡迎在下面的評論框中告訴我。",-1)),a[52]||(a[52]=s("p",null,[s("em",null,"（題圖：MJ/188e0c86-ed52-4185-b583-23814fb72ce7）")],-1)),a[53]||(a[53]=s("hr",null,null,-1)),s("p",null,[a[31]||(a[31]=i("via: ",-1)),n(l,{href:"https://www.debugpoint.com/wayland-arch-linux/"},{default:e(()=>[...a[30]||(a[30]=[i("https://www.debugpoint.com/wayland-arch-linux/",-1)])]),_:1})]),s("p",null,[a[35]||(a[35]=i("作者：",-1)),n(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...a[32]||(a[32]=[i("Arindam",-1)])]),_:1}),a[36]||(a[36]=i(" 選題：",-1)),n(l,{href:"https://github.com/lkxed/"},{default:e(()=>[...a[33]||(a[33]=[i("lkxed",-1)])]),_:1}),a[37]||(a[37]=i(" 譯者：ChatGPT 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:e(()=>[...a[34]||(a[34]=[i("wxy",-1)])]),_:1})]),s("p",null,[a[40]||(a[40]=i("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[38]||(a[38]=[i("LCTT",-1)])]),_:1}),a[41]||(a[41]=i(" 原創編譯，",-1)),n(l,{href:"https://linux.cn/"},{default:e(()=>[...a[39]||(a[39]=[i("Linux中國",-1)])]),_:1}),a[42]||(a[42]=i(" 榮譽推出",-1))])])}const w=d(g,[["render",h]]);export{f as __pageData,w as default};
